  // ------------------------------------------------------------------ Merkle tree

  const node = (left, right) => fromHex(sha256Hex(concat(Uint8Array.of(1), left, right)));

  /** RFC 9162 section 2.1.3.2: does `path` take the entry at `index` to `root` in a tree of `size` leaves? */
