    'proof.envelope': 'PP5501',
    'proof.statement': 'PP5502',
    'proof.subject': 'PP5503',
    'proof.model': 'PP5504',
    'proof.verifier': 'PP5505',
    'proof.verdict': 'PP5506',
    'proof.tcb': 'PP5507',
